WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_new_burst_tier, DATE_TRUNC('WEEK', started_at) AS week_start, COUNT(*) FILTER (WHERE browser = 'Edge') AS edge_rows, APPROX_PERCENTILE(is_new_burst, 0.9) AS is_new_burst_p90, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, DENSE_RANK() OVER (PARTITION BY CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END ORDER BY COUNT(*) FILTER (WHERE browser = 'Edge') DESC) AS edge_rows_dense_rank FROM sessionized GROUP BY CASE WHEN is_new_burst >= 1 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', started_at) HAVING is_new_burst_p90 > 0
